(function(){
 const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
 const getState=()=>{try{return JSON.parse(localStorage.getItem('nawaf-hq-v3')||'null')}catch{return null}};
 function clickText(text){const el=$$('button').find(b=>b.textContent.includes(text));if(el){el.click();return true}return false}
 function addCommandDock(){if($('#hq-command-dock'))return;const main=$('.main');if(!main)return;const dock=document.createElement('section');dock.id='hq-command-dock';dock.className='hq-command-dock card';dock.innerHTML='<div class="dock-copy"><span class="eyebrow">CEO COMMAND CENTER</span><b>وش تبغى الشركة تسوي الآن؟</b><small>أي نشاط يبدأ من توجيهك، وما يظهر إنجاز بدون دليل.</small></div><div class="dock-actions"><button id="hq-start-command" class="primary">✦ أعطِ توجيهًا للشركة</button><button id="hq-open-board">◎ افتح مجلس الشركة</button></div>';$('.greeting')?.insertAdjacentElement('afterend',dock);$('#hq-start-command').onclick=()=>typeof window.NawafHQ?.commandView==='function'?window.NawafHQ.commandView():clickText('بسم الله')||clickText('توجيه الشركة')||$('#manager-core')?.click();$('#hq-open-board').onclick=()=>window.NawafCompanyBoard?.open?.('company')||clickText('مجلس الشركة')}
 function statusLabel(x){return({READY:'جاهز',IDLE:'متاح',WORKING:'يعمل',RESEARCHING:'يبحث',COLLABORATING:'يتعاون',REVIEWING:'يراجع',WAITING_FOR_NAWAF:'بانتظار نواف'})[x]||x||'جاهز'}
 function person(s,id,fallback,role){const e=(s?.employees||[]).find(x=>x.id===id)||{};return {id,name:e.name||fallback,role:e.role||role,status:e.status||'READY',task:e.currentTask||e.task||''}}
 function openPerson(id){if(typeof window.NawafHQ?.employeeView==='function')return window.NawafHQ.employeeView(id);if(id==='sara')return window.NawafCompanyBoard?.open?.('company');const row=$(`.employee[data-id="${id}"]`);if(row)return row.click();alert('مساحة الموظف مرتبطة بلوحة الموظفين الحالية.')}
 function robotMarkup(p){return `<button class="iso-person state-${p.status.toLowerCase()}" data-agent="${p.id}" aria-label="${p.name}"><div class="iso-bot"><div class="antenna"></div><div class="head"><span></span><span></span></div><div class="body"><i></i></div><div class="arm left"></div><div class="arm right"></div></div><div class="iso-tag"><b>${p.name}</b><small>${statusLabel(p.status)}</small></div></button>`}
 function deskMarkup(kind='code'){return `<div class="iso-desk ${kind}"><div class="desk-surface"></div><div class="monitor m1"><i></i><b></b><em></em></div><div class="monitor m2"><i></i><b></b><em></em></div><div class="chair"></div></div>`}
 function plantMarkup(cls=''){return `<div class="iso-plant ${cls}"><i></i><i></i><i></i><span></span></div>`}
 function buildOffice(){const office=$('.office');if(!office||office.dataset.hqBuilt==='iso')return;office.dataset.hqBuilt='iso';office.className=office.className.replace(/hq-office-v\d+/g,'').trim()+' hq-office-iso';const s=getState();const sara=person(s,'sara','سارة','المدير العام AI'),omar=person(s,'omar','عمر','التقنية والبحث'),lian=person(s,'lian','ليان','المنتج والتجربة'),noura=person(s,'noura','نورة','الجودة والمراجعة');office.innerHTML=`<div class="iso-world"><header class="iso-topbar"><div><span class="ops-live"><i></i> NAWAF HQ · LIVE OFFICE</span><h2>المقر التفاعلي</h2><p>مكتب حي يعكس الحالات الحقيقية للموظفين</p></div><button class="ops-council">مجلس الشركة</button></header><div class="iso-campus"><div class="campus-glow"></div><div class="iso-corridor c1"></div><div class="iso-corridor c2"></div><div class="iso-corridor c3"></div><div class="iso-corridor c4"></div>
 <section class="iso-room boardroom"><div class="room-wall"><strong>مجلس الشركة</strong><small>BOARDROOM</small></div><div class="meeting-table-wide"><i></i><i></i><i></i><i></i><span></span></div>${plantMarkup('a')}${plantMarkup('b')}<button class="room-action board-action">فتح المجلس</button></section>
 <section class="iso-room tech-room"><div class="room-wall"><strong>التقنية والبحث</strong><small>TECH & RESEARCH</small></div>${deskMarkup('code')}${robotMarkup(omar)}${plantMarkup('a')}</section>
 <section class="iso-room product-room"><div class="room-wall"><strong>المنتج والتجربة</strong><small>PRODUCT & UX</small></div>${deskMarkup('design')}${robotMarkup(lian)}${plantMarkup('b')}</section>
 <section class="iso-room quality-room"><div class="room-wall"><strong>الجودة والمراجعة</strong><small>QUALITY</small></div>${deskMarkup('quality')}${robotMarkup(noura)}${plantMarkup('a')}</section>
 <section class="iso-room gm-room"><div class="room-wall"><strong>الإدارة العامة</strong><small>GENERAL MANAGEMENT</small></div>${deskMarkup('gm')}${robotMarkup(sara)}${plantMarkup('b')}</section>
 <section class="iso-room analytics-room"><div class="room-wall"><strong>مركز التحليلات</strong><small>ANALYTICS</small></div><div class="data-wall"><i></i><i></i><i></i><i></i><i></i></div><div class="analytics-desk"><span></span><span></span></div><em class="room-note">يعرض البيانات الموثّقة فقط</em></section>
 <section class="iso-hub"><div class="hub-ring r1"></div><div class="hub-ring r2"></div><div class="hub-orb"><span>N</span></div><b>NAWAF HQ</b><small>COMMAND CORE</small></section>
 ${plantMarkup('hub-p1')}${plantMarkup('hub-p2')}${plantMarkup('hub-p3')}${plantMarkup('hub-p4')}
 </div><footer class="ops-footer"><span><i></i> الحالات مرتبطة بالعمل الحقيقي فقط</span><small>اضغط على أي روبوت لفتح مساحة الموظف</small></footer></div>`;$('.ops-council',office).onclick=()=>window.NawafCompanyBoard?.open?.('company')||clickText('مجلس الشركة');$('.board-action',office).onclick=()=>window.NawafCompanyBoard?.open?.('company')||clickText('مجلس الشركة');$$('[data-agent]',office).forEach(b=>b.onclick=()=>openPerson(b.dataset.agent))}
 function fixBrand(){const b=$('.brand');if(b)b.innerHTML='NAWAF <span>HQ</span><small>AI COMPANY OS</small>';document.title='NAWAF HQ — لوحة القيادة'}
 function addTruthStatus(){if($('#truth-status'))return;const top=$('.topbar');if(!top)return;const x=document.createElement('div');x.id='truth-status';x.className='truth-status';x.innerHTML='<i></i><span>وضع العمل الموثّق</span><small>لا نشاط وهمي</small>';top.appendChild(x)}
 function addQuickProjectLabels(){$$('.project').forEach(p=>{const n=$('b',p)?.textContent?.trim();if(n&&!$('.project-kind',p)){const t=document.createElement('small');t.className='project-kind';t.textContent=n==='قدّها'?'مشروع الألعاب':n==='مُعِين'?'التطبيق الإسلامي':'مشروع';p.querySelector('span')?.appendChild(t)}})}
 function boot(){fixBrand();addCommandDock();buildOffice();addTruthStatus();addQuickProjectLabels()}
 const mo=new MutationObserver(()=>{clearTimeout(window.__hqEnhance);window.__hqEnhance=setTimeout(boot,80)});mo.observe(document.documentElement,{childList:true,subtree:true});document.readyState==='loading'?document.addEventListener('DOMContentLoaded',boot):boot();
})();